#!/usr/bin/env bun
/**
 * Keep `src/db/migrations.generated.ts` in step with `drizzle/<name>/migration.sql`.
 *
 * The deployed artifact is one compiled binary, so the SQL has to be **in** the
 * bundle: there is no `drizzle/` directory next to the installed binary, and a
 * loader that reads files (`import.meta.glob` in a bundle, `readdirSync` under
 * `bun`) is two code paths with two behaviours. Generating one plain module
 * leaves a single one, importable by the runner, the tests and the e2e harness
 * alike.
 *
 * The generated file is committed, and three things keep it honest:
 *   - this script's `--check` mode, which `build` and `build:exe` run first;
 *   - the `migrations` gate in `scripts/verify.ts`, which runs the same check
 *     under `bun run verify`;
 *   - `scripts/ensure-db.ts`, which regenerates it before `bun run dev` migrates.
 *
 * Usage:
 *   bun scripts/generate-migrations.ts          # write, when the file is stale
 *   bun scripts/generate-migrations.ts --check  # fail when stale, write nothing
 */
import { existsSync, readFileSync, readdirSync, writeFileSync } from "fs";
import { join } from "path";
import { fileURLToPath } from "url";

const packageDir = fileURLToPath(new URL("..", import.meta.url));
const drizzleDir = join(packageDir, "drizzle");
const outputPath = join(packageDir, "src", "db", "migrations.generated.ts");
const checkOnly = process.argv.includes("--check");

/** Migration directory names, oldest first — the order they are applied in. */
function migrationNames() {
  return readdirSync(drizzleDir, { withFileTypes: true })
    .filter((entry) => existsSync(join(drizzleDir, entry.name, "migration.sql")))
    .map((entry) => entry.name)
    .toSorted();
}

/** The exact file content the chain on disk describes. */
function render(names) {
  const entries = names.map((name) => {
    const sql = readFileSync(join(drizzleDir, name, "migration.sql"), "utf-8");
    return `  { name: ${JSON.stringify(name)}, sql: ${JSON.stringify(sql)} },`;
  });
  return `// Generated by scripts/generate-migrations.ts — do not edit by hand.
// Rebuild it with: bun run --filter @courier/server migrations:generate

/**
 * The migrations this build carries, oldest first. A migration's \`name\` is its
 * identity: it is what the ledger records and what decides "already applied".
 */
export const MIGRATIONS: ReadonlyArray<{ name: string; sql: string }> = [
${entries.join("\n")}
];
`;
}

const names = migrationNames();
const expected = render(names);
const current = existsSync(outputPath) ? readFileSync(outputPath, "utf-8") : "";

if (current === expected) {
  if (checkOnly) {
    process.stdout.write(`[courier:server] migrations chain up to date (${names.length})\n`);
  }
  process.exit(0);
}

if (checkOnly) {
  // Say what differs when the names do; a same-name edit is "content changed".
  const generated = [...current.matchAll(/name: ("[^"]*")/g)].map((match) => JSON.parse(match[1]));
  const missing = names.filter((name) => !generated.includes(name));
  const extra = generated.filter((name) => !names.includes(name));
  const detail = [
    missing.length > 0 ? `missing ${missing.join(", ")}` : "",
    extra.length > 0 ? `no longer in drizzle/: ${extra.join(", ")}` : "",
  ]
    .filter(Boolean)
    .join("; ");

  process.stderr.write(
    `[courier:server] ${outputPath} is stale${detail === "" ? " (content changed)" : ` (${detail})`}.\n` +
      `[courier:server] run: bun run --filter @courier/server migrations:generate\n`,
  );
  process.exit(1);
}

writeFileSync(outputPath, expected, "utf-8");
process.stdout.write(
  `[courier:server] wrote ${names.length} migrations to ${outputPath} (commit it)\n`,
);
